<?php
defined('ABSPATH') || exit;

final class CAFCC_Resources {
    public static function init(){
        add_action('admin_menu',function(){if(CAFCC_Repository::admin_allowed())add_submenu_page('cafcc','ICAI Resources','ICAI Resources','manage_options','cafcc-resources',array(__CLASS__,'screen'));});
        add_action('admin_post_cafcc_resource',function(){if(!CAFCC_Repository::admin_allowed()||!isset($_POST['_wpnonce'])||!is_string($_POST['_wpnonce'])||!wp_verify_nonce(wp_unslash($_POST['_wpnonce']),'cafcc_resource'))wp_die('Administrator permission and a secure request are required.','',array('response'=>403));$input=array();foreach(array('id','title','subject_code','official_url','resource_type','applicability') as $k){if(isset($_POST[$k])&&is_string($_POST[$k]))$input[$k]=wp_unslash($_POST[$k]);}$input['publish_confirmed']=isset($_POST['publish_confirmed']);$r=self::save($input);if(is_wp_error($r))wp_die(esc_html($r->get_error_message()));wp_safe_redirect(admin_url('admin.php?page=cafcc-resources'));exit;});
    }
    public static function save($input){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator access required.',403);if(!is_array($input)||array_diff(array_keys($input),array('id','title','subject_code','official_url','resource_type','applicability','publish_confirmed')))return CAFCC_Repository::error('Unexpected resource fields.');
        $row=array();foreach(array('title'=>190,'subject_code'=>16,'resource_type'=>32,'applicability'=>500) as $key=>$max){$v=$input[$key]??'';if(!is_string($v)||strlen($v)>$max||preg_match('~(?:drive|docs)\.google\.com~i',$v))return CAFCC_Repository::error('Invalid resource field.');$row[$key]=sanitize_text_field($v);}if(!$row['title']||!$row['resource_type']||($row['subject_code']&&!in_array($row['subject_code'],array('FR','AFM','AUDIT','DT','IDT','IBS'),true)))return CAFCC_Repository::error('Choose title, subject and resource type.');$url=CAFCC_Repository::official_url($input['official_url']??'');if(is_wp_error($url)||!$url)return CAFCC_Repository::error('Use a verified official ICAI HTTPS URL.');$row['official_url']=$url;$published=true===($input['publish_confirmed']??false);$row['review_status']=$published?'verified':'needs_review';$row['publication_status']=$published?'published':'draft';$id=CAFCC_Repository::id($input['id']??null,true);if(is_wp_error($id))return $id;return CAFCC_Academic::transaction(function()use($id,$row){global $wpdb;$t=CAFCC_Bank_DB::table('resources');$before=$id?$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d FOR UPDATE",$id),ARRAY_A):null;if($id&&!$before)return CAFCC_Repository::error('Resource not found.',404);if(false===($id?$wpdb->update($t,$row,array('id'=>$id)):$wpdb->insert($t,$row)))return CAFCC_Repository::error('Cannot save official resource.',500);$savedid=$id?:$wpdb->insert_id;if(!CAFCC_Bank_DB::audit_master('resources',$savedid,$before,$row))return CAFCC_Repository::error('Cannot retain resource audit.',500);return array_merge($row,array('id'=>$savedid));});
    }
    public static function directory(){global $wpdb;$t=CAFCC_Bank_DB::table('resources');$rows=$wpdb->get_results("SELECT title,subject_code,official_url,resource_type,applicability FROM $t WHERE review_status='verified' AND publication_status='published' ORDER BY subject_code,id LIMIT 200",ARRAY_A);if(!$rows)return '<p>No reviewed official resources have been added yet.</p>';$html='<ul class="cc-resource-directory">';foreach($rows as $r)$html.='<li><strong>'.esc_html($r['subject_code'].' · '.$r['title']).'</strong><p>'.esc_html($r['resource_type'].' · '.$r['applicability']).'</p><a href="'.esc_url($r['official_url']).'" target="_blank" rel="noopener noreferrer">Open official ICAI resource</a></li>';return $html.'</ul>';}
    public static function screen(){if(!CAFCC_Repository::admin_allowed())wp_die('Administrator access required.');echo '<div class="wrap"><h1>ICAI Resources</h1><p>Add original reference metadata and official links. Private Drive links are rejected. Edits default to draft unless you explicitly reconfirm publication.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('cafcc_resource');echo '<input type="hidden" name="action" value="cafcc_resource">';foreach(array('id'=>'Existing ID to edit (blank for new)','title'=>'Title','subject_code'=>'Subject code (FR/AFM/AUDIT/DT/IDT/IBS)','official_url'=>'Official ICAI URL','resource_type'=>'Resource type','applicability'=>'Applicability') as $k=>$label)echo '<p><label>'.esc_html($label).'<br><input style="width:min(680px,95%)" name="'.esc_attr($k).'"'.(in_array($k,array('title','official_url','resource_type'),true)?' required':'').'></label></p>';echo '<label><input type="checkbox" name="publish_confirmed"> I verified this official resource and its applicability; publish this saved revision.</label><p><button class="button button-primary">Save resource</button></p></form><h2>Student directory</h2>'.self::directory().'</div>';}
}
